//! P3-02 archive-adapter tests. Happy paths use the **committed** fixture
//! archives (`tests/fixtures/`, generated by `generate_fixtures.py`);
//! attack archives (traversal, links, bombs) are crafted in-test with the
//! same zip/tar crates the adapter reads, so the malicious structure is
//! explicit. Everything runs in temp staging directories; nothing touches
//! real paths (testing-strategy.md).

use std::fs;
use std::io::{Cursor, Write};
use std::path::Path;

use devkit_core::error::ErrorCode;
use devkit_download::CancelToken;
use devkit_install::{extract_bytes, ArchiveError, ArchiveLimits, ExtractedFile};
use sha2::{Digest, Sha256};
use tempfile::TempDir;

fn staging() -> (TempDir, std::path::PathBuf) {
    let dir = TempDir::new().unwrap();
    let staging = dir.path().join("staging");
    fs::create_dir_all(&staging).unwrap();
    (dir, staging)
}

fn cancel() -> CancelToken {
    CancelToken::new()
}

/// The fixture content set (mirrors generate_fixtures.py).
fn fixture_files() -> Vec<(&'static str, Vec<u8>)> {
    vec![
        (
            "app/bin/tool.exe",
            [b"MZ".to_vec(), vec![b'A'; 100]].concat(),
        ),
        ("app/bin/readme.txt", b"DevKit fixture archive\n".to_vec()),
        (
            "app/lib/core.dat",
            (0u16..256).map(|b| b as u8).cycle().take(4096).collect(),
        ),
        ("app/README.md", b"# fixture archive\n".to_vec()),
    ]
}

fn fixture_path(name: &str) -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join(name)
}

fn sha256_hex(bytes: &[u8]) -> String {
    let digest = Sha256::digest(bytes);
    digest.iter().map(|byte| format!("{byte:02x}")).collect()
}

/// Builds a zip archive in memory with the exact entry names given
/// (no sanitization — that is the point when crafting attacks).
fn craft_zip(entries: &[(&str, Vec<u8>)]) -> Vec<u8> {
    let cursor = Cursor::new(Vec::new());
    let mut writer = zip::ZipWriter::new(cursor);
    for (name, data) in entries {
        writer
            .start_file(name.to_string(), zip::write::SimpleFileOptions::default())
            .unwrap();
        writer.write_all(data).unwrap();
    }
    writer.finish().unwrap().into_inner()
}

/// Builds a tar.gz in memory with arbitrary entry names/types.
fn craft_tar_gz(entries: &[(&str, tar::EntryType, Vec<u8>)]) -> Vec<u8> {
    let encoder =
        flate2::write::GzEncoder::new(Cursor::new(Vec::new()), flate2::Compression::default());
    let mut builder = tar::Builder::new(encoder);
    for (name, kind, data) in entries {
        let mut header = tar::Header::new_gnu();
        header.set_size(data.len() as u64);
        header.set_entry_type(*kind);
        builder
            .append_data(&mut header, name, Cursor::new(data.clone()))
            .unwrap();
    }
    builder.into_inner().unwrap().finish().unwrap().into_inner()
}

/// Builds a raw ustar header block by hand — needed for hostile names
/// like `../evil.txt`, which the tar *writer* refuses to produce.
fn raw_ustar_header(name: &str, size: u64, typeflag: u8) -> [u8; 512] {
    let mut block = [0u8; 512];
    block[..name.len()].copy_from_slice(name.as_bytes());
    let write_field = |field: &mut [u8], value: u64, width_digits: usize| {
        let text = format!("{:0width$o}", value, width = width_digits);
        field[..text.len()].copy_from_slice(text.as_bytes());
        field[text.len()] = b'\0';
    };
    write_field(&mut block[100..108], 0o644, 7); // mode
    write_field(&mut block[108..116], 0, 7); // uid
    write_field(&mut block[116..124], 0, 7); // gid
    write_field(&mut block[124..136], size, 11); // size
    write_field(&mut block[136..148], 0, 11); // mtime
    block[148..156].fill(b' '); // checksum placeholder
    block[156] = typeflag;
    block[257..263].copy_from_slice(b"ustar\0");
    block[263..265].copy_from_slice(b"00");
    let sum: u32 = block.iter().map(|byte| u32::from(*byte)).sum();
    let checksum = format!("{:06o}\0 ", sum);
    block[148..156].copy_from_slice(checksum.as_bytes());
    block
}

/// Tar.gz whose entries bypass the tar writer's own sanitization.
fn craft_hostile_tar_gz(entries: &[(&str, u64)]) -> Vec<u8> {
    let mut stream = Vec::new();
    for (name, size) in entries {
        stream.extend_from_slice(&raw_ustar_header(name, *size, b'0'));
        let padded = size.div_ceil(512) * 512;
        stream.extend(std::iter::repeat_n(0u8, padded as usize));
    }
    stream.extend_from_slice(&[0u8; 1024]); // end-of-archive marker
    let mut encoder = flate2::write::GzEncoder::new(Vec::new(), flate2::Compression::default());
    encoder.write_all(&stream).unwrap();
    encoder.finish().unwrap()
}

fn assert_code(error: &ArchiveError, code: ErrorCode) {
    assert_eq!(error.code(), code, "unexpected error: {error}");
}

fn files_in_staging(staging: &Path) -> Vec<std::path::PathBuf> {
    fn walk(dir: &Path, out: &mut Vec<std::path::PathBuf>) {
        for entry in fs::read_dir(dir).unwrap() {
            let path = entry.unwrap().path();
            if path.is_dir() {
                walk(&path, out);
            } else {
                out.push(path);
            }
        }
    }
    let mut out = Vec::new();
    walk(staging, &mut out);
    out.sort();
    out
}

#[test]
fn committed_zip_fixture_extracts_exactly_where_the_receipt_says() {
    let bytes = fs::read(fixture_path("happy.zip")).unwrap();
    let (_dir, staging) = staging();

    let result = extract_bytes(&bytes, &staging, &ArchiveLimits::default(), &cancel()).unwrap();

    let expected: Vec<ExtractedFile> = fixture_files()
        .into_iter()
        .map(|(name, data)| ExtractedFile {
            relative_path: devkit_install::validate_entry_path(name).unwrap(),
            size_bytes: data.len() as u64,
            sha256_hex: sha256_hex(&data),
        })
        .collect();
    // Same file set, same order-independent content, exact sizes/hashes.
    let mut actual = result.files.clone();
    actual.sort_by(|a, b| a.relative_path.cmp(&b.relative_path));
    let mut expected = expected;
    expected.sort_by(|a, b| a.relative_path.cmp(&b.relative_path));
    assert_eq!(actual, expected);

    // Bytes land exactly where the receipt says.
    for file in &result.files {
        let expected_content = fixture_files()
            .into_iter()
            .find(|(name, _)| {
                devkit_install::validate_entry_path(name).unwrap() == file.relative_path
            })
            .unwrap()
            .1;
        let on_disk = fs::read(staging.join(&file.relative_path)).unwrap();
        assert_eq!(on_disk, expected_content);
    }
    // Nothing extra was created.
    assert_eq!(files_in_staging(&staging).len(), 4);
    assert_eq!(result.total_bytes, 4239); // 102 + 23 + 4096 + 18
}

#[test]
fn committed_tar_gz_fixture_extracts_identically() {
    let bytes = fs::read(fixture_path("happy.tar.gz")).unwrap();
    let (_dir, staging) = staging();

    let result = extract_bytes(&bytes, &staging, &ArchiveLimits::default(), &cancel()).unwrap();

    let mut names: Vec<String> = result
        .files
        .iter()
        .map(|file| file.relative_path.to_string_lossy().replace('\\', "/"))
        .collect();
    names.sort();
    assert_eq!(
        names,
        vec![
            "app/README.md",
            "app/bin/readme.txt",
            "app/bin/tool.exe",
            "app/lib/core.dat"
        ]
    );
    let tool = fs::read(staging.join("app").join("bin").join("tool.exe")).unwrap();
    assert_eq!(tool.len(), 102);
    assert_eq!(&tool[..2], b"MZ");
    assert_eq!(files_in_staging(&staging).len(), 4);
}

#[test]
fn zip_slip_traversal_is_rejected_with_integrity_code_and_nothing_extracted() {
    let bytes = craft_zip(&[("../evil.txt", b"escaped".to_vec())]);
    let (_dir, staging) = staging();

    let error = extract_bytes(&bytes, &staging, &ArchiveLimits::default(), &cancel()).unwrap_err();

    assert_code(&error, ErrorCode::IntegrityCheckFailed);
    assert!(
        matches!(error, ArchiveError::UnsafeEntryPath { .. }),
        "{error}"
    );
    assert!(files_in_staging(&staging).is_empty());
}

#[test]
fn late_traversal_entry_quarantines_the_partially_extracted_output() {
    // First entry is benign and gets extracted; the second violates the
    // path policy. Everything extracted so far must be removed.
    let bytes = craft_zip(&[
        ("app/ok.txt", b"fine".to_vec()),
        ("app/../../evil.txt", b"escaped".to_vec()),
    ]);
    let (_dir, staging) = staging();

    let error = extract_bytes(&bytes, &staging, &ArchiveLimits::default(), &cancel()).unwrap_err();

    assert_code(&error, ErrorCode::IntegrityCheckFailed);
    assert!(files_in_staging(&staging).is_empty(), "quarantine failed");
}

#[test]
fn absolute_and_drive_letter_entries_are_rejected() {
    for hostile in ["C:/evil.txt", "/etc/shadow", "\\Windows\\evil"] {
        let bytes = craft_zip(&[(hostile, b"x".to_vec())]);
        let (_dir, staging) = staging();
        let error =
            extract_bytes(&bytes, &staging, &ArchiveLimits::default(), &cancel()).unwrap_err();
        assert_code(&error, ErrorCode::IntegrityCheckFailed);
        assert!(
            matches!(error, ArchiveError::UnsafeEntryPath { .. }),
            "{hostile}: {error}"
        );
    }
}

#[test]
fn zip_symlink_entries_are_rejected() {
    let cursor = Cursor::new(Vec::new());
    let mut writer = zip::ZipWriter::new(cursor);
    writer
        .add_symlink(
            "link.txt",
            "../../../outside.txt",
            zip::write::SimpleFileOptions::default(),
        )
        .unwrap();
    let bytes = writer.finish().unwrap().into_inner();
    let (_dir, staging) = staging();

    let error = extract_bytes(&bytes, &staging, &ArchiveLimits::default(), &cancel()).unwrap_err();

    assert_code(&error, ErrorCode::IntegrityCheckFailed);
    assert!(
        matches!(
            error,
            ArchiveError::LinkEntry {
                kind: "symlink",
                ..
            }
        ),
        "{error}"
    );
    assert!(files_in_staging(&staging).is_empty());
}

#[test]
fn tar_symlink_and_hardlink_entries_are_rejected() {
    for (kind, entry_type) in [
        ("symlink", tar::EntryType::Symlink),
        ("hardlink", tar::EntryType::Link),
    ] {
        let bytes = craft_tar_gz(&[("link", entry_type, Vec::new())]);
        let (_dir, staging) = staging();
        let error =
            extract_bytes(&bytes, &staging, &ArchiveLimits::default(), &cancel()).unwrap_err();
        assert_code(&error, ErrorCode::IntegrityCheckFailed);
        assert!(
            matches!(error, ArchiveError::LinkEntry { kind: k, .. } if k == kind),
            "{kind}: {error}"
        );
        assert!(files_in_staging(&staging).is_empty());
    }
}

#[test]
fn tar_traversal_entry_is_rejected() {
    // Crafted from raw ustar blocks: the tar writer itself refuses `..`.
    let bytes = craft_hostile_tar_gz(&[("../evil.txt", 7)]);
    let (_dir, staging) = staging();

    let error = extract_bytes(&bytes, &staging, &ArchiveLimits::default(), &cancel()).unwrap_err();

    assert_code(&error, ErrorCode::IntegrityCheckFailed);
    assert!(files_in_staging(&staging).is_empty());
}

#[test]
fn zip_bomb_is_caught_by_the_compression_ratio_pre_scan() {
    // 20 MiB of zeros deflate to a few KiB → ratio far above the limit,
    // caught BEFORE any byte is written (pre-scan uses central-directory
    // declared sizes).
    let hostile = craft_zip(&[("bomb.bin", vec![0u8; 20 * 1024 * 1024])]);
    let (_dir, staging) = staging();

    let error =
        extract_bytes(&hostile, &staging, &ArchiveLimits::default(), &cancel()).unwrap_err();

    assert_code(&error, ErrorCode::IntegrityCheckFailed);
    assert!(
        matches!(
            error,
            ArchiveError::BombLimit {
                kind: "compression_ratio",
                ..
            }
        ),
        "{error}"
    );
    assert!(files_in_staging(&staging).is_empty());
}

#[test]
fn file_count_limit_is_enforced() {
    let entries: Vec<(String, Vec<u8>)> = (0..600)
        .map(|index| (format!("f{index}.txt"), b"x".to_vec()))
        .collect();
    let entries: Vec<(&str, Vec<u8>)> = entries
        .iter()
        .map(|(name, data)| (name.as_str(), data.clone()))
        .collect();
    let bytes = craft_zip(&entries);
    let (_dir, staging) = staging();
    let limits = ArchiveLimits {
        max_file_count: 500,
        ..ArchiveLimits::default()
    };

    let error = extract_bytes(&bytes, &staging, &limits, &cancel()).unwrap_err();

    assert_code(&error, ErrorCode::IntegrityCheckFailed);
    assert!(
        matches!(
            error,
            ArchiveError::BombLimit {
                kind: "file_count",
                ..
            }
        ),
        "{error}"
    );
}

#[test]
fn tar_total_size_limit_is_enforced_while_streaming() {
    // Tar has no central directory; the cumulative size check must stop
    // the stream. 32 MiB of zeros gzip to a few KiB.
    let bytes = craft_tar_gz(&[(
        "zeros.bin",
        tar::EntryType::Regular,
        vec![0u8; 32 * 1024 * 1024],
    )]);
    let (_dir, staging) = staging();
    let limits = ArchiveLimits {
        max_total_uncompressed: 10 * 1024 * 1024,
        ..ArchiveLimits::default()
    };

    let error = extract_bytes(&bytes, &staging, &limits, &cancel()).unwrap_err();

    assert_code(&error, ErrorCode::IntegrityCheckFailed);
    assert!(
        matches!(
            error,
            ArchiveError::BombLimit {
                kind: "total_size",
                ..
            }
        ),
        "{error}"
    );
    assert!(files_in_staging(&staging).is_empty());
}

#[test]
fn non_archive_bytes_are_reported_as_unsupported() {
    let (_dir, staging) = staging();
    let error = extract_bytes(
        b"this is not an archive",
        &staging,
        &ArchiveLimits::default(),
        &cancel(),
    )
    .unwrap_err();
    assert_code(&error, ErrorCode::IntegrityCheckFailed);
    assert!(matches!(error, ArchiveError::UnsupportedFormat));
}

#[test]
fn truncated_zip_is_reported_as_malformed() {
    let bytes = fs::read(fixture_path("happy.zip")).unwrap();
    let (_dir, staging) = staging();
    let error = extract_bytes(
        &bytes[..100],
        &staging,
        &ArchiveLimits::default(),
        &cancel(),
    )
    .unwrap_err();
    assert_code(&error, ErrorCode::IntegrityCheckFailed);
    assert!(matches!(error, ArchiveError::Malformed(_)), "{error}");
}

#[test]
fn cancellation_before_the_start_leaves_staging_empty() {
    let bytes = fs::read(fixture_path("happy.zip")).unwrap();
    let (_dir, staging) = staging();
    let token = cancel();
    token.cancel();

    let error = extract_bytes(&bytes, &staging, &ArchiveLimits::default(), &token).unwrap_err();

    assert_code(&error, ErrorCode::Cancelled);
    assert!(files_in_staging(&staging).is_empty());
}
